namespace Sentinel\Tests\Integration;
use PHPUnit\Framework\TestCase;
use Sentinel\Core\{HttpException,Request};
use Sentinel\Tests\FieldFixture;

final class ClientWorkflowsTest extends TestCase
{
    private function fixture(): array {
        [$app,$db,$ctx]=FieldFixture::create();
        $db->execute("INSERT INTO client_portal_access(company_id,user_id,client_id) VALUES(101,2,1)");
        $db->execute("INSERT INTO permissions(permission_id,company_id,permission_code,status) VALUES(9001,101,'site_scope.restricted','ACTIVE')");
        return [$app,$db,$ctx];
    }
    private function rejects(callable $fn,int $status): void {try{$fn();self::fail('Expected rejection');}catch(HttpException $e){self::assertSame($status,$e->statusCode(),$e->getMessage());}}
    private function formInput(): array {return ['site_id'=>1,'form_code'=>'GATE','expected_revision'=>0,'title'=>'Gate check','fields'=>[['key'=>'gate','label'=>'Gate secure','type'=>'PASS_FAIL','required'=>true,'photo_required'=>true,'followup_on_fail'=>true],['key'=>'notes','label'=>'Notes','type'=>'TEXT','required'=>false,'photo_required'=>false,'followup_on_fail'=>false]]];}
    private function answers(): array {return ['operation_uuid'=>'11111111-1111-4111-8111-111111111111','answers'=>['gate'=>['value'=>'FAIL','photo_base64'=>'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+aR1cAAAAASUVORK5CYII=']]];}
    private function report($db): void {$db->execute("INSERT INTO published_site_reports(company_id,client_id,site_id,title,report_text,published_by_user_id,published_at) VALUES(101,1,1,'Daily report','Patrol complete.',1,:now)",['now'=>gmdate('Y-m-d H:i:s')]);}
    private function quoteInput(): array {return ['client_id'=>1,'proposed_site_name'=>'New client site','title'=>'Guarding service','currency'=>'ZAR','lines'=>[['description'=>'Monthly guarding','quantity'=>2,'unit_minor'=>10001]],'tax_basis_points'=>1500,'terms'=>'Monthly service; agreed deployment.','valid_until'=>gmdate('Y-m-d',time()+86400)];}
    private function contractFixture($db): void {
        foreach(['branch_id INTEGER','contract_id INTEGER','address TEXT','status TEXT','updated_by_user_id INTEGER']as$column)$db->execute('ALTER TABLE sites ADD COLUMN '.$column);
        $db->execute('CREATE TABLE branches(branch_id INTEGER PRIMARY KEY,company_id INTEGER,client_id INTEGER,status TEXT)');$db->execute("INSERT INTO branches VALUES(1,101,1,'ACTIVE'),(2,101,2,'ACTIVE'),(3,202,3,'ACTIVE')");
        $db->execute('CREATE TABLE contracts(contract_id INTEGER PRIMARY KEY,contract_uuid TEXT,company_id INTEGER,client_id INTEGER,contract_number TEXT,contract_name TEXT,start_date TEXT,end_date TEXT,monthly_value TEXT,required_guard_count INTEGER,shift_requirements_json TEXT,status TEXT,created_by_user_id INTEGER,updated_by_user_id INTEGER,deleted_at TEXT)');
    }
    private function conversion(): array {return ['branch_id'=>1,'contract_number'=>'CNT-NEW','start_date'=>gmdate('Y-m-d'),'end_date'=>null,'required_guards'=>2,'address'=>'Client premises'];}
    private function rosterFixture($db): void {
        foreach(['position_id INTEGER','assignment_status TEXT','deleted_at TEXT']as$c)$db->execute('ALTER TABLE employee_assignments ADD COLUMN '.$c);
        foreach(['person_id INTEGER','employee_number TEXT','psira_number TEXT']as$c)$db->execute('ALTER TABLE employees ADD COLUMN '.$c);
        foreach(['shift_assignment_uuid TEXT','shift_name TEXT','check_in_window_start TEXT','created_at TEXT','updated_at TEXT']as$c)$db->execute('ALTER TABLE shift_assignments ADD COLUMN '.$c);
        $db->execute('CREATE TABLE positions(position_id INTEGER PRIMARY KEY,company_id INTEGER,position_category TEXT,position_status TEXT,deleted_at TEXT)');$db->execute("INSERT INTO positions VALUES(1,101,'GUARD','ACTIVE',NULL)");$db->execute("INSERT INTO employee_assignments VALUES(1,101,1,1,'ACTIVE',NULL),(2,101,2,1,'ACTIVE',NULL)");
        $db->execute('CREATE TABLE people(person_id INTEGER PRIMARY KEY,company_id INTEGER,first_name TEXT,last_name TEXT)');$db->execute("INSERT INTO people VALUES(1,101,'A','Guard'),(2,101,'B','Guard')");$db->execute('UPDATE employees SET person_id=employee_id');$db->execute('CREATE TABLE posts(post_id INTEGER PRIMARY KEY,company_id INTEGER,site_id INTEGER,post_name TEXT,deleted_at TEXT)');
    }
    public function testSiteRestrictionWinsOverBroadRolesAndRevocationIsImmediate(): void {
        [$app,$db,$ctx]=$this->fixture();$scope=$app->container()->make('site_access_service');$auth=$app->container()->make('authorization_service');
        $scope->restrictRole(['role_id'=>2,'restricted'=>true]);$scope->grant(['user_id'=>2,'site_id'=>1]);$db->execute('INSERT INTO user_roles VALUES(2,1,101)');$ctx->setUser('2');
        self::assertTrue($auth->isAllowed('2','inspection_forms.view'));self::assertFalse($auth->isAllowed('2','reports.view'));self::assertFalse($auth->isAllowed('2','guard.self'));self::assertFalse($auth->isAllowed('2','site_access.manage'));self::assertFalse($auth->isAllowed('2','users.view'));self::assertCount(1,$scope->sites());self::assertSame('Own site',$scope->workspace(['site_id'=>1])['site']['site_name']);$this->rejects(fn()=>$scope->workspace(['site_id'=>2]),404);$this->rejects(fn()=>$scope->workspace(['site_id'=>3]),404);
        $ctx->setUser('1');$scope->revoke('1');$ctx->setUser('2');self::assertSame([],$scope->sites());$this->rejects(fn()=>$scope->requireSite(1),404);
    }
    public function testScopeGrantRejectsOtherTenantAndOwnAdministratorRestriction(): void {
        [$app,$db]=$this->fixture();$s=$app->container()->make('site_access_service');$this->rejects(fn()=>$s->grant(['user_id'=>3,'site_id'=>1]),404);$this->rejects(fn()=>$s->grant(['user_id'=>2,'site_id'=>3]),404);$this->rejects(fn()=>$s->restrictRole(['role_id'=>1,'restricted'=>true]),409);$s->grant(['user_id'=>2,'site_id'=>1]);$s->grant(['user_id'=>2,'site_id'=>1]);self::assertCount(1,$s->grants());
    }
    public function testRestrictedJwtCannotUseOldCompanyWideEndpoints(): void {
        [$app,$db]=$this->fixture();$token=$app->jwt()->createToken('2');$db->execute('INSERT INTO user_roles VALUES(2,1,101)');$app->container()->make('site_access_service')->restrictRole(['role_id'=>2,'restricted'=>true]);
        foreach(['/api/v1/reports/attendance','/api/v1/users','/api/v1/guard/workspace','/api/v1/site-access','/api/v1/quotations']as$path){$this->rejects(fn()=>$app->handle(Request::create('GET',$path,[],['Authorization'=>'Bearer '.$token])),403);}
        $response=$app->handle(Request::create('GET','/api/v1/site-workspace/sites',[],['Authorization'=>'Bearer '.$token]));self::assertSame(200,$response->status());
    }
    public function testInspectionRequiredPhotoAndFailureCreatesOneAuditedFollowup(): void {
        [$app,$db]=$this->fixture();$s=$app->container()->make('inspection_forms_service');$id=$s->publish($this->formInput())['id'];$answer=$this->answers();$missing=$answer;unset($missing['answers']['gate']['photo_base64']);$this->rejects(fn()=>$s->submit($id,$missing),422);$first=$s->submit($id,$answer);self::assertSame(1,$first['followups_created']);self::assertSame($first['id'],$s->submit($id,$answer)['id']);$history=$s->history(['site_id'=>1]);self::assertCount(1,$history['submissions']);self::assertCount(1,$history['followups']);self::assertCount(1,$history['submissions'][0]['photos']);$photo=$s->photo((string)$history['submissions'][0]['photos'][0]['photo_id']);self::assertSame('image/png',$photo['mime']);self::assertSame(hash('sha256',$photo['bytes']),$history['submissions'][0]['photos'][0]['sha256']);$s->resolve('1',['resolution'=>'Supervisor secured gate.']);self::assertSame('RESOLVED',$s->history(['site_id'=>1])['followups'][0]['state']);
    }
    public function testInspectionVersionsAndRetryPayloadCannotBeChanged(): void {
        [$app,$db]=$this->fixture();$s=$app->container()->make('inspection_forms_service');$id=$s->publish($this->formInput())['id'];$a=$this->answers();$first=$s->submit($id,$a);$changed=$a;$changed['answers']['gate']['value']='PASS';$this->rejects(fn()=>$s->submit($id,$changed),409);$s->publish([...$this->formInput(),'expected_revision'=>1]);self::assertSame($first['id'],$s->submit($id,$a)['id']);$fresh=$a;$fresh['operation_uuid']='22222222-2222-4222-8222-222222222222';$this->rejects(fn()=>$s->submit($id,$fresh),409);self::assertCount(1,$s->templates(['site_id'=>1]));$this->rejects(fn()=>$s->publish($this->formInput()),409);
    }
    public function testInspectionScopeAppliesToHistoryPhotosAndFollowups(): void {
        [$app,$db,$ctx]=$this->fixture();$s=$app->container()->make('inspection_forms_service');$id=$s->publish($this->formInput())['id'];$s->submit($id,$this->answers());$scope=$app->container()->make('site_access_service');$scope->restrictRole(['role_id'=>2,'restricted'=>true]);$scope->grant(['user_id'=>2,'site_id'=>2]);$ctx->setUser('2');foreach([fn()=>$s->history(['site_id'=>1]),fn()=>$s->photo('1'),fn()=>$s->resolve('1',['resolution'=>'Forged']),fn()=>$s->submit($id,$this->answers())]as$fn)$this->rejects($fn,404);
    }
    public function testInspectionTypedAnswersRejectUnknownFieldsAndInvalidPhotos(): void {
        [$app]=$this->fixture();$s=$app->container()->make('inspection_forms_service');$id=$s->publish($this->formInput())['id'];$a=$this->answers();$a['answers']['gate']['photo_base64']=base64_encode('not an image');$this->rejects(fn()=>$s->submit($id,$a),422);$a=$this->answers();$a['answers']['gate']['value']=true;$this->rejects(fn()=>$s->submit($id,$a),422);$a=$this->answers();$a['answers']['unknown']=['value'=>'x'];$this->rejects(fn()=>$s->submit($id,$a),422);
    }
    public function testClientRequestsKeepInternalNotesPrivateAndRequireClientConfirmation(): void {
        [$app,$db,$ctx]=$this->fixture();$s=$app->container()->make('client_care_service');$ctx->setUser('2');$id=$s->create(['site_id'=>1,'request_type'=>'COMPLAINT','title'=>'Gate left open','description'=>'Please investigate.'],true)['id'];$ctx->setUser('1');$db->execute("UPDATE client_requests SET response_due_at='2026-01-01 00:00:00'");$s->action($id,'begin',['expected_revision'=>1,'message'=>'Private review','audience'=>'INTERNAL']);self::assertTrue($s->requests(['site_id'=>1])[0]['response_overdue']);$s->action($id,'reply',['expected_revision'=>2,'message'=>'We are investigating.','audience'=>'CLIENT']);self::assertFalse($s->requests(['site_id'=>1])[0]['response_overdue']);$s->action($id,'resolve',['expected_revision'=>3,'message'=>'Gate repaired.']);$this->rejects(fn()=>$s->action($id,'confirm',['expected_revision'=>4,'message'=>'Close it']),409);$ctx->setUser('2');self::assertStringNotContainsString('Private review',json_encode($s->history($id,true)));self::assertSame('CLOSED',$s->action($id,'confirm',['expected_revision'=>4,'message'=>'Confirmed repaired.'],true)['state']);self::assertNotNull($s->requests(['site_id'=>1],true)[0]['confirmed_at']);$this->rejects(fn()=>$s->action($id,'reply',['expected_revision'=>5,'message'=>'Later'],true),409);
    }
    public function testClientCanReopenAndCannotReadAnotherClientOrForgeAudience(): void {
        [$app,$db,$ctx]=$this->fixture();$s=$app->container()->make('client_care_service');$id=$s->create(['site_id'=>1,'request_type'=>'REQUEST','title'=>'Light','description'=>'Check light.'])['id'];$s->action($id,'resolve',['expected_revision'=>1,'message'=>'Checked.']);$ctx->setUser('2');self::assertSame('OPEN',$s->action($id,'reopen',['expected_revision'=>2,'message'=>'Still broken.'],true)['state']);$this->rejects(fn()=>$s->requests(['site_id'=>2],true),404);$this->rejects(fn()=>$s->action($id,'reply',['expected_revision'=>3,'message'=>'Hidden','audience'=>'INTERNAL'],true),422);$db->execute('DELETE FROM client_portal_access');$this->rejects(fn()=>$s->history($id,true),404);
    }
    public function testReportAcknowledgementBindsExactContentAndQuestionsToSameSite(): void {
        [$app,$db,$ctx]=$this->fixture();$this->report($db);$s=$app->container()->make('client_care_service');$ctx->setUser('2');$report=$s->reportsForReview()[0];$s->acknowledge('1',['expected_hash'=>$report['report_hash']]);$s->acknowledge('1',['expected_hash'=>$report['report_hash']]);self::assertSame(1,(int)$db->fetch('SELECT COUNT(*) AS n FROM client_report_reviews')['n']);$db->execute("UPDATE published_site_reports SET report_text='Corrected report.'");self::assertNull($s->reportsForReview()[0]['my_acknowledgement']);$this->rejects(fn()=>$s->acknowledge('1',['expected_hash'=>$report['report_hash']]),409);$ctx->setUser('1');self::assertFalse($s->reviews(['site_id'=>1])[0]['matches_current_report']);$this->rejects(fn()=>$s->create(['site_id'=>2,'request_type'=>'REPORT_QUESTION','title'=>'Question','description'=>'Wrong client report','related_report_id'=>1]),404);$ctx->setUser('2');self::assertNotEmpty($s->create(['site_id'=>1,'request_type'=>'REPORT_QUESTION','title'=>'Question','description'=>'Explain the correction.','related_report_id'=>1],true)['id']);
    }
    public function testSiteClientReassignmentDoesNotExposePriorClientRequests(): void {
        [$app,$db,$ctx]=$this->fixture();$s=$app->container()->make('client_care_service');$id=$s->create(['site_id'=>1,'request_type'=>'COMPLAINT','title'=>'Prior client issue','description'=>'Private prior-client details'])['id'];$db->execute('UPDATE sites SET client_id=2 WHERE site_id=1');$db->execute('INSERT INTO client_portal_access VALUES(101,2,2)');$ctx->setUser('2');self::assertSame([],$s->requests(['site_id'=>1],true));$this->rejects(fn()=>$s->history($id,true),404);$this->rejects(fn()=>$s->action($id,'reply',['expected_revision'=>1,'message'=>'Attempt'],true),404);
    }
    public function testLeaveApprovalRequiresReliefAndRejectsOverlappingAbsence(): void {
        [$app,$db,$ctx]=$this->fixture();$s=$app->container()->make('availability_service');$body=['employee_id'=>2,'request_type'=>'LEAVE','starts_at'=>'2027-01-01 08:00:00','ends_at'=>'2027-01-01 18:00:00','reason'=>'Annual leave'];$id=$s->request($body)['id'];$db->execute("INSERT INTO shift_assignments(shift_assignment_id,company_id,employee_id,shift_start_at,shift_end_at,assignment_status) VALUES(1,101,2,'2027-01-01 10:00:00','2027-01-01 12:00:00','ASSIGNED')");$this->rejects(fn()=>$s->review($id,'approve',['expected_revision'=>1,'notes'=>'Review']),409);$db->execute("UPDATE shift_assignments SET assignment_status='CANCELLED'");$s->review($id,'approve',['expected_revision'=>1,'notes'=>'Relief arranged']);$this->rejects(fn()=>$s->assertAvailable('2','2027-01-01 17:00:00','2027-01-01 19:00:00'),409);$s->assertAvailable('2','2027-01-01 18:00:00','2027-01-01 19:00:00');$second=$s->request($body)['id'];$this->rejects(fn()=>$s->review($second,'approve',['expected_revision'=>1,'notes'=>'Overlap']),409);$ctx->setUser('2');self::assertCount(2,$s->list(true));$this->rejects(fn()=>$s->review($id,'approve',['expected_revision'=>2,'notes'=>'Self approve'],true),404);$s->review($id,'cancel',['expected_revision'=>2,'notes'=>'Plans changed'],true);$s->assertAvailable('2',$body['starts_at'],$body['ends_at']);
    }
    public function testLeaveSelfServiceDerivesEmployeeAndRejectsTenantEscape(): void {
        [$app,$db,$ctx]=$this->fixture();$s=$app->container()->make('availability_service');$body=['request_type'=>'UNAVAILABLE','starts_at'=>'2027-01-02 08:00:00','ends_at'=>'2027-01-02 18:00:00','reason'=>'Appointment'];$ctx->setUser('2');$this->rejects(fn()=>$s->request([...$body,'employee_id'=>1],true),422);$s->request($body,true);self::assertSame(2,(int)$s->list(true)[0]['employee_id']);$ctx->setUser('1');self::assertSame([],$s->list(true));$this->rejects(fn()=>$s->review('1','cancel',['expected_revision'=>1,'notes'=>'Forged'],true),404);$ctx->setTenantId(202);self::assertSame([],$s->list());$this->rejects(fn()=>$s->review('1','approve',['expected_revision'=>1,'notes'=>'Forged']),404);
    }
    public function testApprovedAbsenceBlocksRealShiftCreateUpdateAndRelief(): void {
        [$app,$db]=$this->fixture();$this->rosterFixture($db);$leave=$app->container()->make('availability_service');$date=gmdate('Y-m-d',time()+86400);$id=$leave->request(['employee_id'=>2,'request_type'=>'LEAVE','starts_at'=>$date.' 08:00:00','ends_at'=>$date.' 18:00:00','reason'=>'Approved leave'])['id'];$leave->review($id,'approve',['expected_revision'=>1,'notes'=>'No assigned duty']);
        $shifts=$app->container()->make('shift_assignment_management_service');$body=['employee_id'=>2,'site_id'=>1,'assignment_date'=>$date,'shift_name'=>'Day','shift_start_at'=>$date.' 10:00:00','shift_end_at'=>$date.' 12:00:00'];$this->rejects(fn()=>$shifts->createShiftAssignment($body),409);$created=$shifts->createShiftAssignment([...$body,'employee_id'=>1]);$this->rejects(fn()=>$shifts->updateShiftAssignment((string)$created['shift_assignment_id'],['employee_id'=>2]),409);$this->rejects(fn()=>$app->container()->make('control_room_service')->relief((string)$created['shift_assignment_id'],['expected_employee_id'=>1,'replacement_employee_id'=>2,'reason'=>'Try unavailable guard']),409);
        $leave->review($id,'cancel',['expected_revision'=>2,'notes'=>'Leave withdrawn']);self::assertTrue($app->container()->make('control_room_service')->relief((string)$created['shift_assignment_id'],['expected_employee_id'=>1,'replacement_employee_id'=>2,'reason'=>'Available again'])['assigned']);
    }
    public function testQuotationArithmeticPortalDecisionAndDraftImmutability(): void {
        [$app,$db,$ctx]=$this->fixture();$s=$app->container()->make('quotation_service');$id=$s->create($this->quoteInput())['id'];self::assertSame(23002,(int)$s->detail($id)['total_minor']);$ctx->setUser('2');self::assertSame([],$s->list(true));$this->rejects(fn()=>$s->detail($id,true),404);$ctx->setUser('1');$share=$s->share($id,['expected_revision'=>1]);$this->rejects(fn()=>$s->update($id,[...$this->quoteInput(),'expected_revision'=>2]),409);$ctx->setUser('2');self::assertCount(1,$s->list(true));$this->rejects(fn()=>$s->decide($id,'accept',['expected_hash'=>str_repeat('0',64),'notes'=>'Accept']),409);self::assertSame('ACCEPTED',$s->decide($id,'accept',['expected_hash'=>$share['shared_hash'],'notes'=>'Approved offer.'])['state']);self::assertSame(2,(int)$s->detail($id,true)['accepted_by_user_id']);$this->rejects(fn()=>$s->decide($id,'accept',['expected_hash'=>$share['shared_hash'],'notes'=>'Repeat']),409);
    }
    public function testAcceptedQuotationConvertsOnceAndActivationRequiresAllEvidence(): void {
        [$app,$db,$ctx]=$this->fixture();$this->contractFixture($db);$s=$app->container()->make('quotation_service');$id=$s->create($this->quoteInput())['id'];$hash=$s->share($id,['expected_revision'=>1])['shared_hash'];$ctx->setUser('2');$s->decide($id,'accept',['expected_hash'=>$hash,'notes'=>'Accept']);$ctx->setUser('1');$this->rejects(fn()=>$s->convert($id,[...$this->conversion(),'branch_id'=>2]),422);$this->rejects(fn()=>$s->convert($id,[...$this->conversion(),'branch_id'=>3]),404);$created=$s->convert($id,$this->conversion());self::assertSame($created,$s->convert($id,$this->conversion()));self::assertSame(1,(int)$db->fetch('SELECT COUNT(*) AS n FROM contracts')['n']);$this->rejects(fn()=>$s->convert($id,[...$this->conversion(),'address'=>'Changed']),409);$o=$s->onboardings()[0];self::assertCount(7,$o['tasks']);$this->rejects(fn()=>$s->activate($created['onboarding_id']),409);foreach($o['tasks']as$t)$s->completeTask((string)$t['task_id'],['expected_revision'=>1,'evidence_reference'=>'Reviewed evidence record '. $t['task_id']]);self::assertTrue($s->activate($created['onboarding_id'])['activated']);self::assertSame('ACTIVE',$db->fetch('SELECT status FROM contracts')['status']);self::assertSame('ACTIVE',$db->fetch('SELECT status FROM sites WHERE site_id=:id',['id'=>$created['site_id']])['status']);$this->rejects(fn()=>$s->activate($created['onboarding_id']),409);
    }
    public function testQuoteTamperingExpiryAndMappingRemovalBlockAcceptance(): void {
        [$app,$db,$ctx]=$this->fixture();$s=$app->container()->make('quotation_service');$id=$s->create($this->quoteInput())['id'];$hash=$s->share($id,['expected_revision'=>1])['shared_hash'];$ctx->setUser('2');$db->execute("UPDATE service_quotations SET terms='Altered after sharing'");$this->rejects(fn()=>$s->decide($id,'accept',['expected_hash'=>$hash,'notes'=>'Accept']),409);$db->execute('DELETE FROM client_portal_access');$this->rejects(fn()=>$s->detail($id,true),404);self::assertSame([],$s->list(true));
    }
    public function testAuditFailureRollsBackInspectionAndClientIssue(): void {
        [$app,$db]=$this->fixture();$forms=$app->container()->make('inspection_forms_service');$id=$forms->publish($this->formInput())['id'];$db->execute("CREATE TRIGGER reject_audit BEFORE INSERT ON audit_logs BEGIN SELECT RAISE(ABORT,'audit unavailable');END");foreach([fn()=>$forms->submit($id,$this->answers()),fn()=>$app->container()->make('client_care_service')->create(['site_id'=>1,'request_type'=>'REQUEST','title'=>'Check','description'=>'Check gate'])]as$fn){try{$fn();self::fail('Expected audit failure');}catch(\PDOException){self::assertTrue(true);}}self::assertSame(0,(int)$db->fetch('SELECT COUNT(*) AS n FROM inspection_form_submissions')['n']);self::assertSame(0,(int)$db->fetch('SELECT COUNT(*) AS n FROM client_requests')['n']);
    }
